  function getLightThemeTextPatch(style, index) {
    const normalizedStyle = normalizeUiStyle(style);
    if (!LIGHT_TEXT_PATCH_STYLES.has(normalizedStyle)) return null;

    const patches = LIGHT_THEME_TEXT_PALETTES[normalizedStyle];
    if (!Array.isArray(patches) || !patches.length) return null;
    const paletteIndex = Math.max(0, Math.min(patches.length - 1, Math.round(Number(index) || 0)));
    return { ...patches[paletteIndex] };
  }

