  function normalizeUiStyleFavorites(value) {
    const allowed = new Set(getUiStyleDefinitions().map(style => style.value));
    const seen = new Set();
    const result = [];

    (Array.isArray(value) ? value : []).forEach(item => {
      const style = normalizeUiStyle(item, '');
      if (!style || !allowed.has(style) || seen.has(style)) return;
      seen.add(style);
      result.push(style);
    });

    return result;
  }

  function readUiStyleFavorites() {
    try {
      return normalizeUiStyleFavorites(JSON.parse(localStorage.getItem(SGB_UI_STYLE_FAVORITES_KEY) || '[]'));
    } catch (_) {
      return [];
    }
  }

  function writeUiStyleFavorites(value) {
    const favorites = normalizeUiStyleFavorites(value);
    try {
      localStorage.setItem(SGB_UI_STYLE_FAVORITES_KEY, JSON.stringify(favorites));
    } catch (_) {}
    return favorites;
  }

  function toggleUiStyleFavorite(style) {
    const normalized = normalizeUiStyle(style, '');
    if (!normalized) return readUiStyleFavorites();

    const favorites = readUiStyleFavorites();
    const index = favorites.indexOf(normalized);
    if (index >= 0) favorites.splice(index, 1);
    else favorites.push(normalized);
    return writeUiStyleFavorites(favorites);
  }

