  const SHARED_RUNTIME_KEY = '__SGB_BACKGROUND_RUNTIME_V3__';
  const SHARED_RUNTIME_OWNER = `scene-painter-${VERSION}`;

  function getLiveSharedRuntimeOwner() {
    if (window.CrackCustomRoomBackground?.getState) return 'custom-room';
    if (window.CSPGeneratedBackgroundBlur?.getState) return 'scene-painter';
    return '';
  }

  function claimSharedRuntime() {
    const liveOwner = getLiveSharedRuntimeOwner();
    const claimedOwner = String(window[SHARED_RUNTIME_KEY] || '').trim();
    if (liveOwner || claimedOwner) {
      console.warn(
        `[${SCRIPT_NAME}] 다른 배경 테마 배포본(${liveOwner || claimedOwner})이 이미 실행/부팅 중이라 중복 실행을 막았습니다.`
      );
      return false;
    }
    window[SHARED_RUNTIME_KEY] = SHARED_RUNTIME_OWNER;
    return true;
  }

  function releaseSharedRuntime() {
    if (window[SHARED_RUNTIME_KEY] === SHARED_RUNTIME_OWNER) {
      try {
        delete window[SHARED_RUNTIME_KEY];
      } catch (_) {
        window[SHARED_RUNTIME_KEY] = '';
      }
    }
  }

  function log(...args) {
    if (CONFIG.debug) console.log(`[${SCRIPT_NAME}]`, ...args);
  }

  function setAttributeIfChanged(element, name, value) {
    if (!(element instanceof Element)) return;
    const next = String(value);
    if (element.getAttribute(name) !== next) element.setAttribute(name, next);
  }

  function safeJsonParse(value, fallback = {}) {
    try {
      return value ? JSON.parse(value) : fallback;
    } catch (_) {
      return fallback;
    }
  }

  // Scene Painter 4.35.x부터 room/scene JSON이 fflate gzip 문자열로 저장될 수 있다.
  // 배경 확프는 읽기 전용 호환 계층만 두고 Scene Painter 저장 데이터 자체는 수정하지 않는다.
  const CSP_COMPRESSED_JSON_PREFIX = '__CSP_JSON_GZIP_V1__';

  function cspBase64ToBytes(base64) {
    const binary = atob(String(base64 || ''));
    const bytes = new Uint8Array(binary.length);
    for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
    return bytes;
  }

  function decodeCspLocalJsonValue(value, fallback = {}) {
    const raw = String(value || '');
    if (!raw) return fallback;

    if (raw.startsWith(CSP_COMPRESSED_JSON_PREFIX)) {
      try {
        const codec = globalThis.fflate || window.fflate;
        if (!codec?.gunzipSync || !codec?.strFromU8) {
          console.warn(`[${SCRIPT_NAME}] Scene Painter 압축 기록을 읽을 fflate를 찾지 못했습니다.`);
          return fallback;
        }
        const payload = raw.slice(CSP_COMPRESSED_JSON_PREFIX.length);
        const json = codec.strFromU8(codec.gunzipSync(cspBase64ToBytes(payload)));
        return JSON.parse(json);
      } catch (err) {
        console.warn(`[${SCRIPT_NAME}] Scene Painter 압축 scene_records 해제 실패:`, err);
        return fallback;
      }
    }

    return safeJsonParse(raw, fallback);
  }

  function clampValue(value, min, max, fallback) {
    const n = Number(value);
    if (!Number.isFinite(n)) return fallback;
    return Math.max(min, Math.min(max, n));
  }

  function normalizeHexColor(value, fallback) {
    const raw = String(value || '').trim();
    if (/^#[0-9a-fA-F]{6}$/.test(raw)) return raw.toLowerCase();

    const short = raw.match(/^#([0-9a-fA-F]{3})$/);
    if (short) {
      return `#${short[1].split('').map(ch => ch + ch).join('')}`.toLowerCase();
    }

    return fallback;
  }


  function hexToRgbTriplet(hex, fallback = '255,255,255') {
    const value = normalizeHexColor(hex, null);
    if (!value) return fallback;
    const r = parseInt(value.slice(1, 3), 16);
    const g = parseInt(value.slice(3, 5), 16);
    const b = parseInt(value.slice(5, 7), 16);
    return `${r},${g},${b}`;
  }

  


